// RegisterPurchaseHeaderLogic adds business logic to Purchase_Header: a value whose methods are
// triggers (OnInsert, OnModify, OnDelete, OnRename, OnBefore…, OnValidate_<Field>). Every
// registered logic of an enabled app runs, in registration order; the first error stops the
// operation. Call it from an init function (an extension app: from its Register). It panics on a method named like a trigger that the table does not have (a
// misspelled trigger, or a field renamed or removed in the definition), so the program
// does not start with a trigger that would never run.
func RegisterPurchaseHeaderLogic(logic any) {
	checkLogic(PurchaseHeaderTableName, "PurchaseHeader", logic, purchaseHeaderTrigger)
	purchaseHeaderLogic = append(purchaseHeaderLogic, logic)
	purchaseHeaderLogicApp = append(purchaseHeaderLogicApp, extensions.Current())
}

// purchaseHeaderTrigger reports whether name is a trigger of Purchase_Header and
// whether logic implements it with the right signature.
func purchaseHeaderTrigger(name string, logic any) (known, ok bool) {
	switch name {
	case "OnInsert":
		_, ok = logic.(PurchaseHeaderOnInsert)
	case "OnModify":
		_, ok = logic.(PurchaseHeaderOnModify)
	case "OnDelete":
		_, ok = logic.(PurchaseHeaderOnDelete)
	case "OnRename":
		_, ok = logic.(PurchaseHeaderOnRename)
	case "OnBeforeInsert":
		_, ok = logic.(PurchaseHeaderOnBeforeInsert)
	case "OnBeforeModify":
		_, ok = logic.(PurchaseHeaderOnBeforeModify)
	case "OnBeforeDelete":
		_, ok = logic.(PurchaseHeaderOnBeforeDelete)
	case "OnBeforeRename":
		_, ok = logic.(PurchaseHeaderOnBeforeRename)
	default:
		// OnValidate_<Field>(rec) of a stored field
		return purchaseHeaderFields.IsOnValidateTrigger(name, logic, (*PurchaseHeader)(nil))
	}
	return true, ok
}

// SetLogic replaces the registered business logic for this record only (tests); no
